function fibonacci(n) {
  if (n < 0 || !Number.isInteger(n)) {
    throw new Error("n must be a non-negative integer");
  }
  if (n === 0) return 0;
  if (n === 1) return 1;

  let previous = 0;
  let current = 1;
  for (let i = 2; i <= n; i++) {
    const next = previous + current;
    previous = current;
    current = next;
  }
  return current;
}

module.exports.fibonacci = fibonacci;

const value = fibonacci(20);
console.log(`FIBONACCI_20=${value}`);

